ssize_t socket_read(struct file *file, char __user *buf, size_t count, loff_t *ppos)
{
    struct socket *sock = file->private_data;
    struct sk_buff *skb;
    int copied;
    ssize_t ret;

    if ((file->f_flags & O_NONBLOCK) && skb_queue_empty(&sock->sk->sk_receive_queue)) {
        return -EAGAIN;
    }

    if (!buf || count == 0) {
        return -EINVAL;
    }

    skb = skb_dequeue(&sock->sk->sk_receive_queue);
    if (!skb) {
        return -EAGAIN;
    }

    sock->sk->sk_data_processed += skb->len;
    sock->sk->sk_receive_queue.qlen--;
    spin_unlock(&sock->sk->sk_receive_lock);

    copied = copy_to_user(buf, skb->data, skb->len);
    if (copied) {
        ret = -EFAULT;
    } else {
        ret = skb->len;
    }

    kfree_skb(skb);
    return ret;
}

ssize_t read_from_socket(struct file *file, char __user *buf, size_t count, loff_t *ppos)
{
    struct socket *sock = file->private_data;
    struct sk_buff *skb;
    ssize_t ret = 0;

    if ((file->f_flags & O_NONBLOCK) && skb_queue_empty(&sock->sk->sk_receive_queue)) {
        return -EAGAIN;
    }

    if (!access_ok(buf, count)) {
        return -EFAULT;
    }

    wait_for_data(sock);

    spin_lock(&sock->sk->sk_receive_queue.lock);

    skb = skb_peek(&sock->sk->sk_receive_queue);
    if (!skb) {
        spin_unlock(&sock->sk->sk_receive_queue.lock);
        return -EAGAIN;
    }

    skb = __skb_dequeue(&sock->sk->sk_receive_queue);
    spin_unlock(&sock->sk->sk_receive_queue.lock);

    if (count > skb->len) {
        count = skb->len;
    }

    if (copy_to_user(buf, skb->data, count)) {
        ret = -EFAULT;
    } else {
        ret = count;
    }

    kfree_skb(skb);

    return ret;
}

ssize_t sock_read(struct file *file, char __user *buf, size_t count, loff_t *ppos)
{
    struct socket *sock = file->private_data;
    struct sk_buff *skb;
    int err = 0;
    ssize_t ret = 0;

    if (sock->type & SOCK_NONBLOCK && !skb_queue_len(&sock->sk->sk_receive_queue))
        return -EAGAIN;

    if (!buf || count == 0)
        return -EINVAL;

    skb = skb_dequeue(&sock->sk->sk_receive_queue);
    if (!skb)
        return -EAGAIN;

    if (skb->len > count)
        return -EMSGSIZE;

    err = copy_to_user(buf, skb->data, skb->len);
    if (err) {
        ret = -EFAULT;
        goto out;
    }

    ret = skb->len;

out:
    kfree_skb(skb);
    return ret;
}

ssize_t socket_read(struct file *file, char __user *buf, size_t count, loff_t *ppos)
{
    struct socket *sock = file->private_data;
    struct sk_buff *skb;
    ssize_t ret = 0;
    int err = 0;

    if (sock->state != SS_CONNECTED)
        return -EINVAL;

    if (file->f_flags & O_NONBLOCK) {
        if (skb_queue_empty(&sock->sk_receive_queue))
            return -EAGAIN;
    }

    skb = skb_dequeue(&sock->sk_receive_queue);
    if (!skb)
        return -EAGAIN;

    if (copy_to_user(buf, skb->data, skb->len)) {
        ret = -EFAULT;
        goto out;
    }

    ret = skb->len;

out:
    kfree_skb(skb);
