ssize_t read_from_socket(struct file *file, char __user *buf, size_t count, loff_t *ppos)
{
    struct socket *sock = file->private_data;
    struct sk_buff *skb;
    int ret = 0;

    if (sock->flags & O_NONBLOCK) {
        if (skb_queue_empty(&sock->sk->sk_receive_queue))
            return -EAGAIN;
    }

    if (!buf || count == 0)
        return -EINVAL;

    skb = skb_dequeue(&sock->sk->sk_receive_queue);
    if (!skb)
        return -EFAULT;

    ret = copy_to_user(buf, skb->data, skb->len);
    if (ret) {
        sock->sk->sk_backlog.len += 1;
        skb_queue_head(&sock->sk->sk_receive_queue, skb);
        return -EFAULT;
    }

    sock->sk->sk_backlog.len -= 1;
    kfree_skb(skb);

    return skb->len;
}
